(() => {
  const durationSlider = document.getElementById('lgp-duration-slider');
  const durationVal = document.getElementById('lgp-duration-val');
  const statEyeRests = document.getElementById('stat-eye-rests');
  const statMovementBreaks = document.getElementById('stat-movement-breaks');
  const statWaterIntake = document.getElementById('stat-water-intake');
  const timelineList = document.getElementById('timeline-list');

  const timerDisplay = document.getElementById('timer-display');
  const timerNextPrompt = document.getElementById('timer-next-prompt');
  const timerStatus = document.getElementById('timer-status');
  const timerToggleBtn = document.getElementById('timer-toggle-btn');
  const timerResetBtn = document.getElementById('timer-reset-btn');

  let isTimerRunning = false;
  let elapsedSeconds = 0;
  let timerInterval = null;

  function updateSchedule() {
    const hours = parseFloat(durationSlider.value) || 3;
    durationVal.textContent = hours + (hours === 1 ? ' Hour' : ' Hours');

    const totalMinutes = Math.round(hours * 60);
    const eyeRests = Math.floor(totalMinutes / 20);
    const movementBreaks = Math.floor(totalMinutes / 60);
    const waterMl = Math.round(hours * 275);

    statEyeRests.textContent = eyeRests;
    statMovementBreaks.textContent = movementBreaks;
    statWaterIntake.textContent = waterMl + ' ml';

    timelineList.innerHTML = '';
    for (let m = 20; m <= totalMinutes; m += 20) {
      const item = document.createElement('div');
      item.className = 'p-3 rounded-xl border border-slate-200 bg-slate-50 flex items-start gap-3';

      if (m % 60 === 0) {
        item.className = 'p-3 rounded-xl border border-indigo-200 bg-indigo-50/50 flex items-start gap-3';
        item.innerHTML = `
          <span class="font-mono font-bold text-indigo-700 shrink-0 w-12">${m}m</span>
          <div class="text-slate-800">
            <strong class="block text-indigo-950 font-bold">Physical Movement Break (Hour ${m / 60})</strong>
            <span>Stand up, stretch wrists and spine, drink 250ml water.</span>
          </div>
        `;
      } else {
        item.innerHTML = `
          <span class="font-mono font-bold text-slate-500 shrink-0 w-12">${m}m</span>
          <div class="text-slate-700">
            <strong class="block text-slate-900 font-bold">20-20-20 Eye Rest</strong>
            <span>Look at an object at least 20 feet away for 20 seconds.</span>
          </div>
        `;
      }
      timelineList.appendChild(item);
    }
  }

  function formatTimer(sec) {
    const h = String(Math.floor(sec / 3600)).padStart(2, '0');
    const m = String(Math.floor((sec % 3600) / 60)).padStart(2, '0');
    const s = String(sec % 60).padStart(2, '0');
    return `${h}:${m}:${s}`;
  }

  function timerTick() {
    elapsedSeconds++;
    timerDisplay.textContent = formatTimer(elapsedSeconds);

    const nextTwentyMin = Math.ceil((elapsedSeconds + 1) / 1200) * 1200;
    const remainingToBreak = Math.max(0, nextTwentyMin - elapsedSeconds);
    const remM = Math.floor(remainingToBreak / 60);
    const remS = remainingToBreak % 60;
    timerNextPrompt.textContent = `Next 20-20-20 break in: ${remM}m ${String(remS).padStart(2, '0')}s`;

    // Audio chime on 20-minute mark
    if (elapsedSeconds > 0 && elapsedSeconds % 1200 === 0) {
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.2);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 1.2);
      } catch (e) {}
    }
  }

  timerToggleBtn.addEventListener('click', () => {
    if (isTimerRunning) {
      clearInterval(timerInterval);
      isTimerRunning = false;
      timerStatus.textContent = 'Paused';
      timerToggleBtn.textContent = 'Resume';
    } else {
      timerInterval = setInterval(timerTick, 1000);
      isTimerRunning = true;
      timerStatus.textContent = 'Active';
      timerStatus.className = 'text-xs font-bold text-emerald-600 uppercase tracking-wider';
      timerToggleBtn.textContent = 'Pause';
    }
  });

  timerResetBtn.addEventListener('click', () => {
    clearInterval(timerInterval);
    isTimerRunning = false;
    elapsedSeconds = 0;
    timerDisplay.textContent = '00:00:00';
    timerNextPrompt.textContent = 'Next 20-20-20 break in: 20m 00s';
    timerStatus.textContent = 'Stopped';
    timerStatus.className = 'text-xs font-bold text-slate-500 uppercase tracking-wider';
    timerToggleBtn.textContent = 'Start Timer';
  });

  durationSlider.addEventListener('input', updateSchedule);
  document.querySelectorAll('#lgp-presets button').forEach((btn) => {
    btn.addEventListener('click', () => {
      durationSlider.value = btn.dataset.hours;
      updateSchedule();
    });
  });

  updateSchedule();
})();
